<?php
require_once __DIR__ . '/../database/database.php'; require_once __DIR__ . '/../app/auth.php'; require_once __DIR__ . '/../app/layout.php'; requireLogin();
$userId=$_SESSION['user_id']; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??''); $description=trim($_POST['description']??''); if($name==='')$error='Project name is required.'; else{$stmt=$pdo->prepare('INSERT INTO projects (user_id,name,description) VALUES (?,?,?)');$stmt->execute([$userId,$name,$description?:null]);header('Location: projects.php');exit;}}
$stmt=$pdo->prepare("SELECT p.id,p.name,p.description,p.status,p.created_at,(SELECT COUNT(*) FROM goals g WHERE g.project_id=p.id) AS goal_count,(SELECT COUNT(*) FROM goals g WHERE g.project_id=p.id AND g.status IN ('completed','complete','done')) AS completed_goals FROM projects p WHERE p.user_id=? ORDER BY p.created_at DESC");$stmt->execute([$userId]);$projects=$stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projects | Project Continuum</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><div class="app-shell"><?php renderSidebar('projects'); ?><main class="main-content"><header class="page-header"><div><h1>Projects</h1><p>Manage all your projects in one place.</p></div><a href="#new-project" class="button">＋ New Project</a></header>
<section class="toolbar"><label class="search"><input id="project-search" type="search" placeholder="Search projects..."></label><select class="select" aria-label="Status"><option>All Status</option></select><select class="select" aria-label="Sort"><option>Sort by: Recent</option></select></section>
<section class="project-cards" id="project-list"><?php if($projects): foreach($projects as $project): $total=(int)$project['goal_count'];$progress=$total?round(((int)$project['completed_goals']/$total)*100):0; ?><a class="card project-card" href="project.php?id=<?= (int)$project['id'] ?>"><div class="project-icon">⌁</div><div><h3><?= htmlspecialchars($project['name']) ?></h3><p><?= htmlspecialchars($project['description']?:'A personal work-continuity project.') ?></p><span class="badge <?= statusClass($project['status']) ?>"><?= htmlspecialchars(statusLabel($project['status'])) ?></span><span class="metadata"> &nbsp;<?= $total ?> goals · Updated <?= date('M j, Y',strtotime($project['created_at'])) ?></span></div><div class="progress"><strong><?= $progress ?>%</strong><small>Progress</small><div class="progress-line"><span style="width:<?= $progress ?>%"></span></div></div></a><?php endforeach; else:?><div class="card panel"><p class="empty">No projects yet. Create one below to begin.</p></div><?php endif;?></section>
<section class="card panel" id="new-project" style="margin-top:24px"><h2 class="panel-title">Create a Project</h2><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="field"><label for="name">Project name</label><input id="name" name="name" maxlength="150" required placeholder="e.g. Project Continuum – Version 1"></div><div class="field"><label for="description">Description</label><input id="description" name="description" placeholder="What are you continuing?"></div><button class="button" type="submit">Create Project</button></form></section>
</main></div><script>document.getElementById('project-search').addEventListener('input',e=>document.querySelectorAll('.project-card').forEach(card=>card.hidden=!card.innerText.toLowerCase().includes(e.target.value.toLowerCase())))</script></body></html>
